// Simulación de los registros procesados en la jornada
const solicitudes = [
  { id: "DEV-1115", monto: 19990, ruta: "APROBACION" },
  { id: "DEV-1116", monto: 69980, ruta: "REVISION" },
  { id: "DEV-1117", monto: 24990, ruta: "RECHAZO" },
  { id: "DEV-1118", monto: 79990, ruta: "REVISION" },
  { id: "DEV-1119", monto: 45990, ruta: "RECHAZO" },
  { id: "DEV-1120", monto: 89990, ruta: "REVISION" },
  { id: "DEV-1121", monto: 289990, ruta: "RECHAZO" },
  { id: "DEV-1122", monto: 45990, ruta: "REVISION" },
  { id: "DEV-1123", monto: 39980, ruta: "RECHAZO" },
  { id: "DEV-1124", monto: 49980, ruta: "REVISION" },
  { id: "DEV-1125", monto: 34990, ruta: "RECHAZO" },
  { id: "DEV-1126", monto: 79990, ruta: "RECHAZO" },
  { id: "DEV-C01", monto: 9990, ruta: "APROBACION" },
  { id: "DEV-C02", monto: 289990, ruta: "REVISION" },
  { id: "DEV-C03", monto: 79990, ruta: "RECHAZO" }
];

let res = {
  total_solicitudes: solicitudes.length,
  aprobadas_cant: 0, aprobadas_monto: 0,
  revision_cant: 0, revision_monto: 0,
  rechazo_cant: 0, rechazo_monto: 0,
  monto_total_dia: 0
};

for (let item of solicitudes) {
  res.monto_total_dia += item.monto;
  if (item.ruta === "APROBACION") {
    res.aprobadas_cant++;
    res.aprobadas_monto += item.monto;
  } else if (item.ruta === "REVISION") {
    res.revision_cant++;
    res.revision_monto += item.monto;
  } else if (item.ruta === "RECHAZO") {
    res.rechazo_cant++;
    res.rechazo_monto += item.monto;
  }
}

res.tasa_aprobacion_automatica = ((res.aprobadas_cant / res.total_solicitudes) * 100).toFixed(2) + "%";

return [{ json: res }];
